def retirer(stock, article, quantite):
    if article not in stock or quantite <= 0:
        return None
    if stock[article] < quantite:
        return None
    copie = stock.copy()
    copie[article] = copie[article] - quantite
    return copie

def manque(stock, article, demande):
    disponible = stock.get(article, 0)
    if demande > disponible:
        return demande - disponible
    return 0
